        // Differences 0 or 1 → Brown
        assert_eq!(determine_winner(0, 0), "Brown");
        assert_eq!(determine_winner(5, 5), "Brown");
        assert_eq!(determine_winner(7, 6), "Brown");
        assert_eq!(determine_winner(6, 7), "Brown");

        // Difference greater than 1 → Alice
        assert_eq!(determine_winner(0, 2), "Alice");
        assert_eq!(determine_winner(2, 0), "Alice");
